async award(userId: string, amount: number, reason: string) {
  await this.dataSource.transaction(async (manager) => {
    const wallet = await manager.findOneOrFail(Wallet, { where: { userId }, lock: { mode: "pessimistic_write" } });
    wallet.points += amount;
    await this.outbox.save({ aggregateType: "wallet", aggregateId: userId,
      eventType: "points.awarded", payload: { userId, amount, reason, balance: wallet.points } });
    if (wallet.points > MAX_POINTS) throw new BadRequestException("balance cap reached");
    await manager.save(wallet);
  });
}
// this.outbox is injected with @InjectRepository(OutboxEvent): it is bound to the DataSource, not to manager.

Statement: "When the balance cap check throws, the wallet change is rolled back but the points.awarded outbox row stays committed, and the relay will publish it."

CREATE TABLE outbox (
  id         uuid PRIMARY KEY,
  event_type text NOT NULL,
  payload    jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  status     text NOT NULL DEFAULT 'pending'
);

-- completeLesson, one transaction:
BEGIN;
INSERT INTO lesson_progress (user_id, lesson_id) VALUES ('u_77', 'l_12');
INSERT INTO outbox (id, event_type, payload) VALUES (gen_random_uuid(), 'lesson.completed', '{...}');
INSERT INTO outbox (id, event_type, payload) VALUES (gen_random_uuid(), 'course.completed', '{...}');
COMMIT;

-- relay:
SELECT id, event_type FROM outbox WHERE status = 'pending' ORDER BY created_at LIMIT 100;

Statement: "The relay reads lesson.completed before course.completed, because the first row was inserted earlier and got an earlier created_at."
